You can save this as a plugin.
(function(alias){Scene_Menu.prototype.createWindowLayer=function(){alias.call(this);this._windowLayer.alpha=0;};})(Scene_Menu.prototype.createWindowLayer);
(function(alias){Scene_Menu.prototype.update=function(){alias.call(this);this._windowLayer.alpha+=0.05;};})(Scene_Menu.prototype.update);

This should work.
But there is a problem, the plugin adds the background outside of the window layer, so it can't fade with the menu itself. It still looks like 2 layers. Unless you also modify the extraimage plugin to put the image inside the window layer.
JavaScript:
(function (alias) {
  Scene_Menu.prototype.create = function () {
    alias.apply(this, arguments);
    this._windowLayer.alpha = 0;
    this._extraImages.forEach(extraImage => {
      extraImage.alpha = 0;
    });
  };
})(Scene_Menu.prototype.create);
(function (alias) {
  Scene_Menu.prototype.update = function () {
    alias.apply(this, arguments);
    this._windowLayer.alpha += 0.01;
  };
})(Scene_Menu.prototype.update);

Sprite_SceneExtra.prototype.updateOpacity = function(){
  this.opacity = this._data.Opacity * (SceneManager._scene._windowLayer?SceneManager._scene._windowLayer.alpha:1);
}

